INSERT INTO public.mcq_banks (id, subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order)
SELECT s.id, 'physics', 6, 'الفيزياء الحديثة', s.section, 'ar', s.question, s.choices, s.answer_index,
       'أسئلة اختيار من متعدد - الفصل السادس: الفيزياء الحديثة', s.sort_order
FROM seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.mcq_banks b
  WHERE b.subject = 'physics' AND b.chapter = 6 AND b.language = 'ar' AND b.question = s.question
)
ON CONFLICT (id) DO NOTHING;

